'use strict';
const D=window.LENS_DATA,$=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sources=new Map(D.sources.map(x=>[x.id,x])),metrics=new Map(D.metrics.map(x=>[x.id,x])),records=new Map(D.benchmarks.map(x=>[x.id,x]));
const directions={higher:'较高通常更有利',lower:'较低通常更有利',lower_abs:'绝对偏差越小越好',target:'需匹配目标值',tradeoff:'存在权衡，不单向排序'};
const kinds={trial_protocol:'原始试验方案',paper:'原始研究论文',author_manuscript:'论文作者稿（版本见来源）',peer_reviewed_paper:'同行评议研究论文',conference_paper:'会议论文',workshop_paper:'研讨会论文',supplementary_material:'论文补充材料（同一研究）',paper_review:'学术综述',scholarly_book:'学术书章',standard:'标准 / 公开预览',manufacturer:'厂商资料',manufacturer_technical:'原厂技术文档',software_documentation:'原厂软件文档'};
const kindOrder={trial_protocol:3,paper:0,author_manuscript:0,peer_reviewed_paper:0,conference_paper:0,workshop_paper:0,supplementary_material:0,paper_review:1,scholarly_book:2,standard:3,manufacturer_technical:4,software_documentation:4,manufacturer:5};
let selected='app_25',tab='metrics';
function current(){return D.applications.find(a=>a.id===selected)||D.applications[0]}
function refs(ids){return '<div class="inline-refs">'+[...new Set(ids)].map(id=>{const s=sources.get(id);return s?`<button data-source="${esc(id)}">${esc(s.title)}</button>`:''}).join(' · ')+'</div>'}
function sourceCard(s){return `<article class="source-item"><span class="source-kind">${esc(kinds[s.kind]||s.kind)}</span><h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></h3>${s.doi?`<p>DOI：${esc(s.doi)}</p>`:''}<p><b>原文位置：</b>${esc(s.location)}</p><p><b>所读范围：</b>${esc(s.evidence_scope)}</p><p>核验日期：${esc(s.checked_on)} · ${s.verification==='inherited_v2'?'沿用 V2 核验记录':s.verification==='checked_excerpt'?'本轮核验相关内容':'未核验状态'}</p></article>`}
function openDialog(title,body){$('detailTitle').textContent=title;$('detailBody').innerHTML=body;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0}
function openSource(id){const s=sources.get(id);if(s)openDialog('核验出处',sourceCard(s))}
function openMetric(id){const m=metrics.get(id);if(!m)return;openDialog(m.name,`<p>${esc(m.english_name)} · 单位：${esc(m.unit)}</p><p>${esc(m.definition)}</p><h3>比较前必须约定</h3><ul>${m.required_conditions.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><div class="notice green"><b>“最佳”如何解释</b>${esc(m.best_interpretation)}</div><h3>定义依据</h3>${m.definition_refs.map(id=>sourceCard(sources.get(id))).join('')}`)}
function recordCard(r,full=false){return `<article class="benchmark"><div class="benchmark-head"><h3>${esc(r.name)}</h3><span class="badge">${esc(r.evidence_type)}</span></div><div class="parameters">${r.parameters.slice(0,full?99:4).map(p=>`<div><span>${esc(p.name)}</span>${esc(p.value)}${full&&p.evidence?`<small class="parameter-evidence">原文位置：${esc(p.evidence.location)}</small>`:''}</div>`).join('')}</div><p><b>适用条件：</b>${esc(r.conditions)}</p>${full?`<p class="small">记录核验：${esc(r.checked_on)} · ${r.record_status==='inherited_v2'?'沿用 V2 核验记录':r.record_status==='checked_excerpt'?'本轮核验相关内容':'未核验状态'}（具体阅读范围见来源）</p><div class="notice"><b>未公开或未核验</b>${esc(r.unreported_or_not_verified)}</div>${r.source_ids.map(id=>sourceCard(sources.get(id))).join('')}`:`<button class="link-button" data-record="${esc(r.id)}">全部 ${r.parameters.length} 项参数、证据与缺口 ↗</button>`}</article>`}
function applicationSources(a){const ids=new Set(a.ranking_gap_refs||[]);a.metric_ids.forEach(id=>metrics.get(id).definition_refs.forEach(x=>ids.add(x)));a.priorities.forEach(p=>p.evidence_refs.forEach(x=>ids.add(x)));a.record_ids.forEach(id=>records.get(id).source_ids.forEach(x=>ids.add(x)));D.bests.filter(b=>b.application_id===a.id).forEach(b=>b.evidence_refs.forEach(x=>ids.add(x)));return [...ids].map(x=>sources.get(x)).sort((a,b)=>(kindOrder[a.kind]??8)-(kindOrder[b.kind]??8))}
function priorityLabel(basis){return basis==='author_explicit'?'作者限定比较':'编辑解读'}
function renderList(){const query=$('search').value.trim().toLowerCase(),category=$('category').value,ranked=$('rankedOnly').checked;
 const list=D.applications.filter(a=>(!category||a.category===category)&&(!ranked||a.priorities.length)&&(!query||[a.name,a.summary,a.category,...a.metric_ids.map(id=>metrics.get(id).name+' '+metrics.get(id).english_name),...a.record_ids.map(id=>records.get(id).name)].join(' ').toLowerCase().includes(query)));
 $('resultCount').textContent=`${list.length} / ${D.applications.length} 类应用`;
 $('appList').innerHTML=list.length?list.map(a=>`<button data-app="${a.id}"${a.id===selected?' aria-current="page"':''}>${esc(a.name)}<small>${a.priorities.length?priorityLabel(a.ranking_status):a.ranking_gap_refs?.length?'有出处的任务权衡':'重要性排序待补证'}</small></button>`).join(''):'<p class="muted">没有匹配项。可清除筛选或搜索具体指标。</p>';
}
function render(){const a=current();$('crumb').textContent=a.category+' / APPLICATION GUIDE';$('appTitle').textContent=a.name;$('appSummary').textContent=a.summary;
 const best=D.bests.filter(b=>b.application_id===a.id);$('coverage').innerHTML=`<div class="counts"><span><b>${a.metric_ids.length}</b>指标定义</span><span><b>${a.record_ids.length}</b>参数样本</span><span><b>${a.priorities.length}</b>优先级层次${a.priorities.length?'（'+priorityLabel(a.ranking_status)+'）':''}</span><span><b>${best.length}</b>限定范围最佳 / 界限</span></div>`;
 document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===tab));b.setAttribute('tabindex',b.dataset.tab===tab?'0':'-1');b.id='tab-'+b.dataset.tab});$('panel').setAttribute('aria-labelledby','tab-'+tab);
 if(tab==='metrics')$('panel').innerHTML=`<div class="notice green"><b>先统一定义，再比较数值</b>${esc(a.metric_mapping_note)} 查看“重要性排序”可区分有证据的建议和待补证内容。</div><div class="metric-list">${a.metric_ids.map(id=>{const m=metrics.get(id);return `<article class="metric"><h2>${esc(m.name)}</h2><div class="english">${esc(m.english_name)} · ${esc(m.unit)}</div><p>${esc(m.definition)}</p><div class="conditions">需约定：${m.required_conditions.map(esc).join(' · ')}</div><div class="foot"><span class="direction">${esc(directions[m.direction])}</span><button class="link-button" data-metric="${id}">定义与出处 ↗</button></div></article>`}).join('')}</div>`;
 if(tab==='priority')$('panel').innerHTML=a.priorities.length?`<div class="notice"><b>${a.ranking_status==='author_explicit'?'作者原文明示的限定任务相对次序</b>P1 / P2 仅编码下列相对关系；不是通用指标总榜，也不是作者给出的数值权重。请先阅读每项适用范围。':'有出处的编辑性优先级，不是文献原文明示排名</b>下列 P1 / P2 表示本库按本页任务整理的设计顺序。同层并列；不代表作者给出这些名次、权重或行业统一要求。每项都可以查看支撑理由的原文位置。'}</div>${a.priorities.map(p=>`<article class="priority-item"><div class="tier">P${p.tier}<small>${priorityLabel(p.basis)}</small></div><div><h2>${p.metric_ids.map(id=>esc(metrics.get(id).name)).join(' / ')}</h2><p>${esc(p.rationale)}</p>${refs(p.evidence_refs)}${p.explicit_rank_location?`<p class="small"><b>相对次序原文位置：</b>${esc(p.explicit_rank_location)}</p>`:''}<p class="small">${esc(p.scope)}</p></div></article>`).join('')}`:`<div class="empty-state"><h2>${a.ranking_gap_refs?.length?'任务权衡：没有统一重要性排序':'尚未建立可引用的重要性排名'}</h2><p>${esc(a.ranking_gap)}</p>${a.ranking_gap_refs?.length?refs(a.ranking_gap_refs):''}<p>已有产品样本与指标定义可用于调研。它们不自动证明“哪个指标最重要”。</p><a href="https://github.com/SelinLee/lens-evidence-atlas/issues/new?template=evidence.yml" target="_blank" rel="noopener">提交该应用的排序依据 ↗</a></div>`;
 if(tab==='best')$('panel').innerHTML=`<div class="notice"><b>“最佳”始终带比较范围</b>当前未建立跨行业世界纪录榜。标准门槛、论文内最佳、理论界限与代表性样本分别呈现；不自动对不同波段、NA、孔径或效率定义的结果排序。</div>${best.length?best.map(b=>`<article class="best-highlight"><span class="scope-label">${b.claim_type==='author_reported_best'?'论文内部最佳结果':b.claim_type==='theoretical_bound'?'理论界限，非实测纪录':'本库同条件记录最优'}</span><strong>${esc(b.display_value)}</strong><p>${esc(b.scope)}</p><p>${Object.entries(b.conditions).map(([k,v])=>esc(k)+': '+esc(Array.isArray(v)?v.join(' / '):v)).join(' · ')}</p><p>原文定位：${esc(b.location)} · 核验 ${esc(b.checked_on)}</p>${refs(b.evidence_refs)}</article>`).join(''):`<div class="empty-state"><h2>该应用的最佳纪录待核验</h2><p>以下是有出处的代表配置或要求，不把单个样本当作最佳。补充纪录时必须定义候选集合与比较口径。</p></div>`}<h2 class="section-title">可核验的参数样本与要求</h2>${a.record_ids.map(id=>recordCard(records.get(id))).join('')}`;
 if(tab==='sources')$('panel').innerHTML=`<div class="notice green"><b>按结论追到原文位置</b>这里汇集本页定义、优先级与样本的来源。原始研究、综述和书章优先展示；规范性要求仍以适用标准为准。未取得全文时会明确证据边界。</div>${applicationSources(a).map(sourceCard).join('')}`;
 renderList();$('live').textContent=a.name+'，'+document.querySelector(`[data-tab="${tab}"]`).textContent;document.title=a.name+' · 透镜评价证据库';
}
function route(){const [id,t]=location.hash.slice(1).split('/');selected=D.applications.some(a=>a.id===id)?id:'app_25';tab=['metrics','priority','best','sources'].includes(t)?t:'metrics';render()}
function method(){openDialog('证据、排名与维护规则',`<h3>如何使用</h3><p>先选择应用，再查定义与必须统一的条件。优先级页明确标记原文排名、编辑性解读或缺证状态；最佳页区分标准限值、论文内最佳、理论界限与代表样本。</p><h3>来源政策</h3><p>${esc(D.meta.source_policy)}。本版不使用维基百科作为关键结论来源。</p><h3>更新流程</h3><ol><li>在 GitHub 新建证据 Issue，提供 DOI/链接、原文位置与适用条件。</li><li>修改 data 下对应应用、指标、来源或记录 JSON。</li><li>运行 npm test 与 npm run build，随 PR 提交生成的 dist。</li><li>核验来源与条件，合并到主分支后通过 GitHub Pages 发布；本项目的源码与查询资料公开。</li></ol><h3>当前覆盖</h3><p>${D.applications.length} 类应用，${D.metrics.length} 个定义，${D.benchmarks.length} 条样本，${D.applications.filter(a=>a.ranking_status==='editorial_synthesis').length} 类应用有带出处的编辑性优先级；${D.applications.filter(a=>a.ranking_status==='author_explicit').length} 类应用包含作者原文明示的限定任务比较。它们不代表跨应用统一名次，世界纪录尚未建立。</p><h3>维护日期</h3><p>旧记录保留 ${esc(D.meta.legacy_checked_on)} 核验日期；本批新增或复核条目单独标记日期与读取范围。目录更新于 ${esc(D.meta.updated_on)}，不代表全库重新核验。</p><p><a href="https://github.com/SelinLee/lens-evidence-atlas" target="_blank" rel="noopener">GitHub 项目 ↗</a></p>`)}
$('provenance').textContent=`目录更新：${D.meta.updated_on}；逐条保留原核验日期`;
$('version').textContent=`v${D.meta.version} · ${D.applications.length} 类应用`;
$('category').insertAdjacentHTML('beforeend',[...new Set(D.applications.map(a=>a.category))].map(x=>`<option>${esc(x)}</option>`).join(''));
['search','category','rankedOnly'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',renderList));
document.addEventListener('click',e=>{const a=e.target.closest('[data-app]'),t=e.target.closest('[data-tab]'),m=e.target.closest('[data-metric]'),s=e.target.closest('[data-source]'),r=e.target.closest('[data-record]');if(a)location.hash=a.dataset.app+'/'+tab;if(t)location.hash=selected+'/'+t.dataset.tab;if(m)openMetric(m.dataset.metric);if(s)openSource(s.dataset.source);if(r)openDialog(records.get(r.dataset.record).name,recordCard(records.get(r.dataset.record),true))});
document.querySelector('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const names=['metrics','priority','best','sources'];let i=names.indexOf(tab);i=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;location.hash=selected+'/'+names[i];document.querySelector(`[data-tab="${names[i]}"]`).focus()});
$('closeDialog').addEventListener('click',()=>$('detail').close());$('methodButton').addEventListener('click',method);window.addEventListener('hashchange',route);route();
